Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0LC_1LC1RD_0RA1LC_1LB1RA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LC_1LC1RD_0RA1LC_1LB1RA
  | 0, 1 => iarm0_1_1RB0LC_1LC1RD_0RA1LC_1LB1RA
  | _, _ => iarm0_0_1RB0LC_1LC1RD_0RA1LC_1LB1RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

