(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB0LC_1LC1RD_0RA1LC_1LB1RA : NeverQuasiHaltsTr tm_1RB0LC_1LC1RD_0RA1LC_1LB1RA.
Proof.
  apply (boardph_neverqhtr tm_1RB0LC_1LC1RD_0RA1LC_1LB1RA pins_1RB0LC_1LC1RD_0RA1LC_1LB1RA FAM 2
                           iarm_1RB0LC_1LC1RD_0RA1LC_1LB1RA 1 1
                           farm_1RB0LC_1LC1RD_0RA1LC_1LB1RA 1 1
                           fm1_1RB0LC_1LC1RD_0RA1LC_1LB1RA fm2_1RB0LC_1LC1RD_0RA1LC_1LB1RA 1 vis_1RB0LC_1LC1RD_0RA1LC_1LB1RA
                           [0] 0 17).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
