(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB0LC_1LC1RD_0RB1LA_0RA1RB : NeverQuasiHaltsTr tm_1RB0LC_1LC1RD_0RB1LA_0RA1RB.
Proof.
  apply (boardph_neverqhtr tm_1RB0LC_1LC1RD_0RB1LA_0RA1RB pins_1RB0LC_1LC1RD_0RB1LA_0RA1RB FAM 1
                           iarm_1RB0LC_1LC1RD_0RB1LA_0RA1RB 1 1
                           farm_1RB0LC_1LC1RD_0RB1LA_0RA1RB 1 1
                           fm1_1RB0LC_1LC1RD_0RB1LA_0RA1RB fm2_1RB0LC_1LC1RD_0RB1LA_0RA1RB 0 vis_1RB0LC_1LC1RD_0RB1LA_0RA1RB
                           [0] 0 22).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0LC_1LC1RD_0RB1LA_0RA1RB.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_1RB0LC_1LC1RD_0RB1LA_0RA1RB.
  - lia.
  - exact iarm_sound_1RB0LC_1LC1RD_0RB1LA_0RA1RB.
  - exact iarm_lhs_1RB0LC_1LC1RD_0RB1LA_0RA1RB.
