  - exact farm_lhs_1RB0LC_1LC1RD_0RB1LA_0RA1RB.
  - exact farm_rhs_1RB0LC_1LC1RD_0RB1LA_0RA1RB.
  - exact farm_cb_1RB0LC_1LC1RD_0RB1LA_0RA1RB.
  - exact vis_ok_1RB0LC_1LC1RD_0RB1LA_0RA1RB.
