(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB0LC_1LC1RD_0RB1LC_1RB1RA : NeverQuasiHaltsTr tm_1RB0LC_1LC1RD_0RB1LC_1RB1RA.
Proof.
  eapply (boardphL_neverqhtr tm_1RB0LC_1LC1RD_0RB1LC_1RB1RA pins_1RB0LC_1LC1RD_0RB1LC_1RB1RA FAM 2
    iarm_1RB0LC_1LC1RD_0RB1LC_1RB1RA 0 1 farm_1RB0LC_1LC1RD_0RB1LC_1RB1RA 1 1 fm1_1RB0LC_1LC1RD_0RB1LC_1RB1RA fm2_1RB0LC_1LC1RD_0RB1LC_1RB1RA padl_1RB0LC_1LC1RD_0RB1LC_1RB1RA padr_1RB0LC_1LC1RD_0RB1LC_1RB1RA
    0 vis_1RB0LC_1LC1RD_0RB1LC_1RB1RA [1] 1).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
