Lemma farm_rhs_1RB0LC_1RC0LD_1LD1RA_0RC1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_rhs (farm_1RB0LC_1RC0LD_1LD1RA_0RC1LD r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_1RB0LC_1RC0LD_1LD1RA_0RC1LD r ph)
