Lemma farm_cb_1RB0LC_1RC0LD_1LD1RA_0RC1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> 0 < lr_cb (farm_1RB0LC_1RC0LD_1LD1RA_0RC1LD r ph).
