Definition fam_1RB0LC_1RC1RA_0RD1LC_1LD1RA : Fam := mkFam 2 [[S1;S1];[S1;S0]] [] [[]] Binary 1 [mkFill 2 [] 0 [1;1] 0] StC S0 false [].
