            ch_iarm0_1_1RB0LC_1RC1RA_0RD1LC_1LD1RA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0LC_1RC1RA_0RD1LC_1LD1RA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LC_1RC1RA_0RD1LC_1LD1RA
  | 0, 1 => iarm0_1_1RB0LC_1RC1RA_0RD1LC_1LD1RA
  | _, _ => iarm0_0_1RB0LC_1RC1RA_0RD1LC_1LD1RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB0LC_1RC1RA_0RD1LC_1LD1RA : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [S1;S0] 1 0 []))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S1;S1] 1 0 [S1;S0;S1])) 4 12.
