(** ** What this board establishes

    16 of 16 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 16 of them
    collapse to 6 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_1RB0LD_0LB1RC_1LA1RA_0RA1LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S1] [] 0 0 [])) 0 2.
Definition ch_iarm0_0_1RB0LD_0LB1RC_1LA1RA_0RA1LD : list rstep := [RB (SWin 2)].
Lemma ok_iarm0_0_1RB0LD_0LB1RC_1LA1RA_0RA1LD :
  check_arm tm true false rules iarm0_0_1RB0LD_0LB1RC_1LA1RA_0RA1LD
            ch_iarm0_0_1RB0LD_0LB1RC_1LA1RA_0RA1LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_1RB0LD_0LB1RC_1LA1RA_0RA1LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S1] [S0;S1;S1] 1 0 [S1;S1;S1]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S0;S1;S1])) 6 8.
Definition ch_iarm0_1_1RB0LD_0LB1RC_1LA1RA_0RA1LD : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWin 2);RB (SCycL 3 0);RB (SWin 3)].
Lemma ok_iarm0_1_1RB0LD_0LB1RC_1LA1RA_0RA1LD :
  check_arm tm true false rules iarm0_1_1RB0LD_0LB1RC_1LA1RA_0RA1LD
            ch_iarm0_1_1RB0LD_0LB1RC_1LA1RA_0RA1LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0LD_0LB1RC_1LA1RA_0RA1LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LD_0LB1RC_1LA1RA_0RA1LD
  | 0, 1 => iarm0_1_1RB0LD_0LB1RC_1LA1RA_0RA1LD
  | _, _ => iarm0_0_1RB0LD_0LB1RC_1LA1RA_0RA1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

