  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S1] [S0;S1;S1] 1 0 [S0;S1]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1;S0;S1])) 6 12.
Definition ch_farm1_0_1RB0LD_0LB1RC_1LA1RA_0RA1LD : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWin 2);RB (SWinR 4);RB (SCycL 3 0);RB (SWin 3)].
