Lemma farm_sound_1RB0LD_0LB1RC_1LA1RA_0RA1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 4 -> RuleSound tm true true (farm_1RB0LD_0LB1RC_1LA1RA_0RA1LD r ph).
Proof.
