    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB0LD_1LC1RA_1LA1LC_0RA1LD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 1]
  | 1, (StA, S1) => [SWin 2;SCycR 2;SWinR 4;SCycL 2 0;SWinL 5]
  | 1, (StB, S0) => [SWin 2;SCycR 2;SWinR 2]
  | 1, (StB, S1) => [SWin 2]
  | 1, (StC, S0) => [SWin 2;SCycR 2;SWinR 4;SCycL 2 0;SWin 2]
  | 1, (StC, S1) => [SWin 2;SCycR 2;SWinR 3]
  | 1, (StD, S0) => []
  | 1, (StD, S1) => [SWin 2;SCycR 2;SWinR 4;SCycL 2 0;SWinL 6]
  | _, _ => []
  end.

