Lemma bootl_1RB0LD_1LC1RA_1LA1RC_0RB1LD :
  stepn tm 7 InitES = Some (lift (fam_cfg FAM ([1;1], 0, 0))).
Proof.
  assert (H : match csteps tm 7 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1;1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

