(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB0LD_1LC1RA_1LA1RC_0RB1LD : NeverQuasiHaltsTr tm_1RB0LD_1LC1RA_1LA1RC_0RB1LD.
Proof.
  eapply (boardphL_neverqhtr tm_1RB0LD_1LC1RA_1LA1RC_0RB1LD pins_1RB0LD_1LC1RA_1LA1RC_0RB1LD FAM 2
    iarm_1RB0LD_1LC1RA_1LA1RC_0RB1LD 0 1 farm_1RB0LD_1LC1RA_1LA1RC_0RB1LD 1 1 fm1_1RB0LD_1LC1RA_1LA1RC_0RB1LD fm2_1RB0LD_1LC1RA_1LA1RC_0RB1LD padl_1RB0LD_1LC1RA_1LA1RC_0RB1LD padr_1RB0LD_1LC1RA_1LA1RC_0RB1LD
    0 vis_1RB0LD_1LC1RA_1LA1RC_0RB1LD [1;1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 1; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0LD_1LC1RA_1LA1RC_0RB1LD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_sound_1RB0LD_1LC1RA_1LA1RC_0RB1LD.
  - exact iarm_lhs_1RB0LD_1LC1RA_1LA1RC_0RB1LD.
  - exact iarm_rhs_1RB0LD_1LC1RA_1LA1RC_0RB1LD.
  - exact iarm_cb_1RB0LD_1LC1RA_1LA1RC_0RB1LD.
