  match r, ph with
  | 1, 0 => farm1_0_1RB0LD_1LC1RA_1RD1RC_0RB1LD
  | _, _ => farm1_0_1RB0LD_1LC1RA_1RD1RC_0RB1LD  (* unreachable: 0 < r < N0 + st *)
  end.

