Qed.

(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB0LD_1LC1RC_1RD1RA_0RB1LD : NeverQuasiHaltsTr tm_1RB0LD_1LC1RC_1RD1RA_0RB1LD.
Proof.
  apply (boardph_neverqhtr tm_1RB0LD_1LC1RC_1RD1RA_0RB1LD pins_1RB0LD_1LC1RC_1RD1RA_0RB1LD FAM 1
