Lemma farm_sound_1RB0LD_1RC0LA_1LB1RA_0RA1LD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_1RB0LD_1RC0LA_1LB1RA_0RA1LD r ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  {
    destruct ph as [|ph].
