Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0LD_1RC0LA_1LD1RA_0RA1LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LD_1RC0LA_1LD1RA_0RA1LD
  | 0, 1 => iarm0_1_1RB0LD_1RC0LA_1LD1RA_0RA1LD
  | 1, 0 => iarm1_0_1RB0LD_1RC0LA_1LD1RA_0RA1LD
  | 1, 1 => iarm1_1_1RB0LD_1RC0LA_1LD1RA_0RA1LD
  | _, _ => iarm0_0_1RB0LD_1RC0LA_1LD1RA_0RA1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB0LD_1RC0LA_1LD1RA_0RA1LD : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0;S1] [S0;S0;S1] 1 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1;S1;S1])) 6 12.
Definition ch_farm1_0_1RB0LD_1RC0LA_1LD1RA_0RA1LD : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWinR 6);RB (SCycL 3 0);RB (SWin 3)].
Lemma ok_farm1_0_1RB0LD_1RC0LA_1LD1RA_0RA1LD :
  check_arm tm true true rules farm1_0_1RB0LD_1RC0LA_1LD1RA_0RA1LD
            ch_farm1_0_1RB0LD_1RC0LA_1LD1RA_0RA1LD = true.
Proof. vm_compute. reflexivity. Qed.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
