    = Some t.
Proof.
  intros r t Hnp H0 Hr.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  { destruct t as [q s]; destruct q, s; try (exfalso; apply Hnp; simpl; tauto); vm_compute; reflexivity. }
  exfalso; lia.
Qed.

(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB0LD_1RC0LA_1LD1RA_0RC1LD : NeverQuasiHaltsTr tm_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
Proof.
  eapply (boardphL_neverqhtr tm_1RB0LD_1RC0LA_1LD1RA_0RC1LD pins_1RB0LD_1RC0LA_1LD1RA_0RC1LD FAM 1
    iarm_1RB0LD_1RC0LA_1LD1RA_0RC1LD 0 1 farm_1RB0LD_1RC0LA_1LD1RA_0RC1LD 1 1 fm1_1RB0LD_1RC0LA_1LD1RA_0RC1LD fm2_1RB0LD_1RC0LA_1LD1RA_0RC1LD padl_1RB0LD_1RC0LA_1LD1RA_0RC1LD padr_1RB0LD_1RC0LA_1LD1RA_0RC1LD
    0 vis_1RB0LD_1RC0LA_1LD1RA_0RC1LD [0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_sound_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
  - exact iarm_lhs_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
  - exact iarm_rhs_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
  - exact iarm_cb_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
  - lia.
  - lia.
  - exact farm_sound_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
  - exact farm_lhs_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
  - exact farm_rhs_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
  - exact farm_cb_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
  - exact vis_ok_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
  - exact bootl_1RB0LD_1RC0LA_1LD1RA_0RC1LD.
Qed.

